export const PET_GEAR_BASE={petHelm:{name:'靈獸角冠',petSlot:'head',cost:65},petCirclet:{name:'靈獸星環',petSlot:'head',cost:65},petArmor:{name:'靈獸戰甲',petSlot:'body',cost:105},petRobe:{name:'靈獸法袍',petSlot:'body',cost:105},petBoots:{name:'靈獸迅足',petSlot:'shoes',cost:70},petGreaves:{name:'靈獸護足',petSlot:'shoes',cost:70}};
export const PET_SLOTS={head:'頭部',body:'身體',shoes:'鞋'};
export const RARITIES=[{id:'common',name:'普通',count:2,weight:700,color:'common'},{id:'rare',name:'稀有',count:3,weight:250,color:'rare'},{id:'uncommon',name:'罕見',count:4,weight:40,color:'uncommon'},{id:'legendary',name:'傳說',count:5,weight:9,color:'legendary'},{id:'mythic',name:'神話',count:6,weight:1,color:'mythic'}];
export const TIER_NAMES=GEAR_TIERS.map(t=>t.name);
export const AFFIX_NAMES={atk:'ATK 物攻',matk:'MATK 魔攻',def:'DEF 防禦',mdef:'MDEF 魔防',hit:'HIT 命中',flee:'FLEE 迴避',crit:'CRIT 暴擊率',STR:'STR 力量',AGI:'AGI 敏捷',VIT:'VIT 體質',INT:'INT 智力',DEX:'DEX 靈巧',LUK:'LUK 幸運',ignoreDef:'無視防禦',critDmg:'暴擊傷害',aspd:'ASPD 攻速',magicDamage:'魔法傷害加成',fleePct:'FLEE 加成',defPct:'防禦加成',hpPct:'HP 加成',aspdPct:'攻速加成',damageReduction:'最終減傷'};
export const PERCENT_AFFIXES=new Set(['ignoreDef','critDmg','magicDamage','fleePct','defPct','hpPct','aspdPct','damageReduction','crit']);
export const SPECIAL_AFFIXES=new Set(['ignoreDef','critDmg','aspdPct','crit','fleePct','damageReduction','hpPct','magicDamage','defPct','aspd']);
export const gearTier=gearTierForLevel;
export const gearGroup=id=>GEAR_BASE[id]?.weaponType?'weapon':'armor';
export const shardId=(group,tier)=>`shard_${group}_${tier}`;
for(let tier=1;tier<=11;tier++)for(const group of ['weapon','armor']){const id=shardId(group,tier);LOOT_ITEMS[id]={name:`${TIER_NAMES[tier-1]}${group==='weapon'?'鋒刃':'護甲'}碎晶`,craft:true,tier,group,cost:0};STACK_IDS.push(id);STACK_SET.add(id);}
export const rarityForRoll=(value=Math.random()*1000)=>{let cursor=0;return RARITIES.find(r=>(cursor+=r.weight)>value)||RARITIES.at(-1);};
export const gearLabel=item=>`${TIER_NAMES[gearTier(item.level)-1]}階 · Lv.${item.level||1} · ${RARITIES.find(r=>r.id===item.rarity)?.name||'普通'} · ${Object.keys(item.affixes||{}).length}詞`;
export const affixLabel=(key,value)=>`${AFFIX_NAMES[key]||key} +${value}${PERCENT_AFFIXES.has(key)?'%':''}`;
export const QUALITY_POWER={common:1,rare:1.12,uncommon:1.28,legendary:1.48,mythic:1.72};
export const PRIMARY_VALUES={atk:12,matk:14,def:5,mdef:4,hp:45,hit:5,flee:5};
function uniqueAttrs(rng){const keys=['STR','AGI','VIT','INT','DEX','LUK'];const first=keys.splice(rand(0,5,rng),1)[0];return [first,keys[rand(0,4,rng)]];}
export function affixRange(key,tier,rarity){const rank=Math.max(0,RARITIES.findIndex(r=>r.id===rarity)),quality=QUALITY_POWER[rarity]||1,power=GEAR_TIERS[tier-1].power;if(PRIMARY_VALUES[key]){const value=PRIMARY_VALUES[key]*power*quality;return [Math.ceil(value*.98),Math.ceil(value*1.02)];}const budgets={hpPct:8,damageReduction:7,fleePct:22,aspdPct:8,crit:24,critDmg:20,ignoreDef:16};if(budgets[key]){const v=budgets[key]*(.4+tier*.1);return [Math.max(1,Math.round(v*.95)),Math.max(1,Math.round(v*1.05))];}const value=key==='crit'?2+tier+rank:key==='aspd'?1+tier*.35+rank*.3:key==='critDmg'?4+tier*2+rank*2:key==='ignoreDef'||key==='magicDamage'?2+tier+rank:key.endsWith('Pct')?2+tier+rank:1+tier*.7+rank*.5;return [Math.max(1,Math.round(value)),Math.max(1,Math.round(value*1.12))];}
function rollValue(key,tier,rarity,rng){const [min,max]=affixRange(key,tier,rarity);return rand(min,max,rng);}
export const primaryAffix=id=>{const base=GEAR_BASE[id]||PET_GEAR_BASE[id];return base?.petSlot?(base.petSlot==='head'?(id==='petCirclet'?'matk':'atk'):base.petSlot==='body'?'hp':'flee'):base?.weaponType?(base.weaponType==='mace'||base.matk>=(base.atk||0)?'matk':'atk'):'def';};
function buildGear(id,level,forceRarity,rng,pet){const base=(pet?PET_GEAR_BASE:GEAR_BASE)[id];if(!base)return null;level=Math.max(1,Math.min(200,Math.floor(level)));const tier=gearTier(level),rarity=RARITIES.find(r=>r.id===forceRarity)||rarityForRoll(Math.min(.999999,rng())*1000),attrs=uniqueAttrs(rng),primary=primaryAffix(id),weapon=!!base.weaponType||pet&&base.petSlot==='head',core=pet?(base.petSlot==='head'?[primary,'hit','DEX']:base.petSlot==='body'?['hp','def','mdef']:['flee','hit','def']):weapon?[primary,'hit','DEX']:['def','mdef','flee'];
 const pool=[...new Set([...core,...attrs,'VIT','INT','LUK','STR','AGI','DEX'])],chosen=weapon?[primary,'hit']:[primary];while(chosen.length<Math.min(5,rarity.count)){const choices=pool.filter(k=>!chosen.includes(k));chosen.push(choices[rand(0,choices.length-1,rng)]);}if(rarity.id==='mythic'){const specials=weapon?['aspdPct','crit','critDmg','ignoreDef']:['fleePct','damageReduction','hpPct'];chosen.push(specials[rand(0,specials.length-1,rng)]);}
 const affixes=Object.fromEntries(chosen.map(k=>[k,rollValue(k,tier,rarity.id,rng)]));if(pet)for(const k of Object.keys(affixes))if(!SPECIAL_AFFIXES.has(k))affixes[k]=Math.round(affixes[k]*(['atk','matk'].includes(k)?1:10/3));
 return {id,uid:`${pet?'pg':'g'}-${Date.now()}-${Math.random().toString(36).slice(2,10)}`,level,tier,rarity:rarity.id,name:`${rarity.name} ${TIER_NAMES[tier-1]}·${base.name}`,affixes,powerVersion:50};}

export function rollGear(id,level=1,forceRarity=null,rng=Math.random){return buildGear(id,level,forceRarity,rng,false);}
export function rollPetGear(id,level=1,forceRarity=null,rng=Math.random){return buildGear(id,level,forceRarity,rng,true);}
export function rebalanceGear(item){if(!item||item.powerVersion===50)return item;let seed=2166136261;for(const ch of String(item.uid||item.id))seed=Math.imul(seed^ch.charCodeAt(0),16777619);const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},pet=!!PET_GEAR_BASE[item.id],base=GEAR_BASE[item.id]||PET_GEAR_BASE[item.id],upgraded=pet?rollPetGear(item.id,item.level,item.rarity,rng):rollGear(item.id,item.level,item.rarity,rng);if(!upgraded)return item;const count=RARITIES.find(r=>r.id===item.rarity)?.count||2,weapon=!!base.weaponType||pet&&base.petSlot==='head',keys=[primaryAffix(item.id),...(weapon?['hit']:[])];for(const key of [...Object.keys(item.affixes||{}),...Object.keys(upgraded.affixes)])if(!SPECIAL_AFFIXES.has(key)&&!keys.includes(key)&&keys.length<Math.min(5,count))keys.push(key);if(item.rarity==='mythic'){const allowed=weapon?['aspdPct','crit','critDmg','ignoreDef']:['fleePct','damageReduction','hpPct'];keys.push(Object.keys(item.affixes||{}).find(k=>allowed.includes(k))||Object.keys(upgraded.affixes).find(k=>allowed.includes(k)));}upgraded.affixes=Object.fromEntries(keys.filter(Boolean).map(key=>[key,Math.round(rollValue(key,upgraded.tier,upgraded.rarity,rng)*(pet&&!SPECIAL_AFFIXES.has(key)&&!['atk','matk'].includes(key)?10/3:1))]));return {...item,...upgraded,uid:item.uid||upgraded.uid,fusionMatch:item.fusionMatch,swapProtected:item.swapProtected};}
export const asStack=(id,qty=1)=>({id,qty});
export const normalizeBag=(bag,items)=>{const out=[];for(const item of Array.isArray(bag)?bag:[]){const entry=typeof item==='string'?{id:item}:item;if(!entry||!items[entry.id])continue;if(items[entry.id].slot||items[entry.id].petSlot){const invalidSpecial=!['legendary','mythic'].includes(entry.rarity)&&Object.keys(entry.affixes||{}).some(k=>SPECIAL_AFFIXES.has(k));const gear=entry.uid&&entry.rarity&&entry.affixes&&!invalidSpecial?entry:items[entry.id].petSlot?rollPetGear(entry.id,entry.level||1,entry.rarity):rollGear(entry.id,entry.level||1,entry.rarity);gear.tier=gearTier(gear.level);out.push(gear);}else{const quantity=Math.max(1,Math.min(100000,Math.floor(entry.qty||1))),old=out.find(x=>x.id===entry.id&&!x.uid);if(old)old.qty=Math.min(100000,old.qty+quantity);else out.push(asStack(entry.id,quantity));}}return out;};
export function addStack(bag,id,qty=1){const existing=bag.find(x=>x.id===id&&!x.uid);if(existing)existing.qty+=qty;else bag.push(asStack(id,qty));}
export function consumeStack(bag,id){const i=bag.findIndex(x=>x.id===id&&!x.uid&&x.qty>0);if(i<0)return false;bag[i].qty--;if(bag[i].qty<=0)bag.splice(i,1);return true;}

export function gearStatValue(item,type){if(!item)return 0;const base=GEAR_BASE[item.id]||PET_GEAR_BASE[item.id];return (item.powerVersion>=23&&type===primaryAffix(item.id)?0:base?.[type]||0)+(item.affixes?.[type]||0);}
export function equipmentDrop(boss=false,lootBonus=0,rng=Math.random){const roll=rng();if(boss)return roll<.9?'character':'pet';const boost=Math.max(0,Math.min(4,1+lootBonus/100));return roll<.18*boost?'character':roll<.2*boost?'pet':null;}
